<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$u=require_auth();try{$d=request_json();$id=(int)($d['postId']??0);v17_content('post',$id,$u);$st=db()->prepare('SELECT 1 FROM saved_posts WHERE user_id=? AND post_id=?');$st->execute([(int)$u['id'],$id]);if($st->fetchColumn()){$st=db()->prepare('DELETE FROM saved_posts WHERE user_id=? AND post_id=?');$st->execute([(int)$u['id'],$id]);$saved=false;}else{$st=db()->prepare('INSERT INTO saved_posts (user_id,post_id) VALUES (?,?)');$st->execute([(int)$u['id'],$id]);$saved=true;}json_response(['saved'=>$saved]);}catch(Throwable $e){json_response(['message'=>'Kaydetme işlemi yapılamadı.'],500);}
